// Get canvas and context
const canvas = document.querySelector("#canvas");
const ctx = canvas.getContext("2d");

// Set canvas to full window size
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

// Particle settings
const TOTAL_PARTICLES = 1500;
const PARTICLES = [];
const MOUSE = { posX: null, posY: null }; // Track mouse position
const ESCAPE_RADIUS = 100; // Distance at which particles react to mouse

// Initialize particles with random properties
for (let i = 0; i < TOTAL_PARTICLES; i++) {
  PARTICLES.push({
    posX: Math.random() * canvas.width, // Random X position
    posY: Math.random() * canvas.height, // Random Y position
    velocityX: (Math.random() - 0.5) * 0.5, // Random X velocity (-0.25 to 0.25)
    velocityY: (Math.random() - 0.5) * 0.5, // Random Y velocity (-0.25 to 0.25)
    baseVelocityX: (Math.random() - 0.5) * 0.5, // Original X velocity to return to
    baseVelocityY: (Math.random() - 0.5) * 0.5, // Original Y velocity to return to
    radius: Math.random() * 3 + 1, // Random size between 1-4
    color: "lightblue", // Consistent particle color
  });
}

// Draw a single particle
function drawParticle(particle) {
  ctx.beginPath();
  ctx.arc(particle.posX, particle.posY, particle.radius, 0, Math.PI * 2);
  ctx.fillStyle = particle.color;
  ctx.fill();
}

// Update particle position and behavior
function updateParticle(particle) {
  const deltaX = particle.posX - MOUSE.posX;
  const deltaY = particle.posY - MOUSE.posY;
  const distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY); // Distance from mouse

  if (distance < ESCAPE_RADIUS && MOUSE.posX !== null) {
    // Scatter away from mouse
    const angle = Math.random() * Math.PI * 2; // Random direction
    const speed = Math.random() * 2 + 0.5; // Random speed (0.5-2.5)
    particle.velocityX = Math.cos(angle) * speed;
    particle.velocityY = Math.sin(angle) * speed;
  } else {
    // Gradually return to original velocity
    particle.velocityX += (particle.baseVelocityX - particle.velocityX) * 0.05;
    particle.velocityY += (particle.baseVelocityY - particle.velocityY) * 0.05;
  }

  // Update position (corrected from previous typo)
  particle.posX += particle.velocityX;
  particle.posY += particle.velocityY;

  // Wrap particles around screen edges
  if (particle.posX < 0) particle.posX = canvas.width;
  if (particle.posX > canvas.width) particle.posX = 0;
  if (particle.posY < 0) particle.posY = canvas.height;
  if (particle.posY > canvas.height) particle.posY = 0;
}

// Animation loop
function animate() {
  ctx.clearRect(0, 0, canvas.width, canvas.height); // Clear canvas

  PARTICLES.forEach((particle) => {
    updateParticle(particle); // Update each particle
    drawParticle(particle); // Draw each particle
  });

  requestAnimationFrame(animate); // Queue next frame
}

// Start animation
animate();

// Update mouse position on movement
canvas.addEventListener("mousemove", (event) => {
  MOUSE.posX = event.clientX;
  MOUSE.posY = event.clientY;
});
